let particles = [];
let numParticles = 500;
let tunnelW = 600;
let tunnelH = 400;
let zFar = -1200;
let zNear = 300;
let blackHoleRad = 70;

class TunnelParticle {
  constructor() {
    this.reset(true); // Random initial Z
  }

  reset(randomZ = false) {
    this.wall = int(random(4)); // 0: Left, 1: Right, 2: Top, 3: Bottom
    this.u = random(-1.0, 1.0);  // Position along wall width/height
    this.z = randomZ ? random(zFar, zNear) : zFar;
    this.speed = random(6.0, 13.0);

    // Color palette: Red, Green, Blue, Yellow, Cyan
    let colors = [
      [0, 85, 95],     // Red
      [120, 85, 95],   // Green
      [220, 85, 95],   // Blue
      [50, 85, 95],    // Yellow
      [180, 85, 95]    // Cyan
    ];
    this.color = random(colors);

    // Sizes (rectangular squares)
    this.w = random(12, 28);
    this.h = random(16, 42);
  }

  update() {
    let lowVal = window.audioLow || 0.0;
    let beatVal = window.beatEnergy || 0.0;
    let speedFactor = 1.0 + lowVal * 2.2 + beatVal * 4.5;
    let weightScale = (window.storyboardWeight !== undefined) ? (window.storyboardWeight / 50.0) : 1.0;
    this.z += this.speed * speedFactor * weightScale;

    if (this.z > zNear) {
      this.reset(false);
    }
  }

  draw() {
    push();
    let x = 0;
    let y = 0;
    let rotX = 0;
    let rotY = 0;

    if (this.wall === 0) { // Left wall
      x = -tunnelW / 2;
      y = this.u * (tunnelH / 2);
      rotY = HALF_PI;
    } else if (this.wall === 1) { // Right wall
      x = tunnelW / 2;
      y = this.u * (tunnelH / 2);
      rotY = -HALF_PI;
    } else if (this.wall === 2) { // Top wall
      x = this.u * (tunnelW / 2);
      y = -tunnelH / 2;
      rotX = HALF_PI;
    } else if (this.wall === 3) { // Bottom wall
      x = this.u * (tunnelW / 2);
      y = tunnelH / 2;
      rotX = -HALF_PI;
    }

    translate(x, y, this.z);
    rotateX(rotX);
    rotateY(rotY);

    colorMode(HSB, 360, 100, 100, 1.0);

    let h = this.color[0];
    let s = this.color[1];
    let b = this.color[2];

    // Blend with chord color if available
    if (window.currentChordColor) {
      let chordC = color(window.currentChordColor);
      let chordH = hue(chordC);
      h = lerp(h, chordH, 0.45);
    }

    // Alpha fade near screen clipping plane or far end
    let alpha = 1.0;
    if (this.z > 150) {
      alpha = map(this.z, 150, zNear, 1.0, 0.0);
    } else if (this.z < -900) {
      alpha = map(this.z, zFar, -900, 0.0, 1.0);
    }

    fill(h, s, b, alpha);
    noStroke();

    rectMode(CENTER);
    rect(0, 0, this.w, this.h);
    pop();
  }
}

function setup() {
  createCanvas(1280, 720, WEBGL);
  colorMode(HSB, 360, 100, 100, 1.0);

  // Initialize particles
  for (let i = 0; i < numParticles; i++) {
    particles.push(new TunnelParticle());
  }

  background(0);
}

function draw() {
  // Fade background slightly to create trails
  push();
  resetMatrix();
  noStroke();
  colorMode(RGB, 255, 255, 255, 1.0);
  fill(0, 0, 0, 0.12); // Persistent trails
  rect(-width/2, -height/2, width, height);
  pop();

  let beatVal = window.beatEnergy || 0.0;
  let lowVal = window.audioLow || 0.0;
  let midVal = window.audioMid || 0.0;
  let highVal = window.audioHigh || 0.0;

  // Enhance camera shake & spin based on beat energy
  let rotZ = sin(frameCount * 0.005) * (0.05 + beatVal * 0.04);
  let rotY = cos(frameCount * 0.004) * (0.04 + beatVal * 0.03);
  let rotX = sin(frameCount * 0.003) * (0.03 + beatVal * 0.02);
  let shake = beatVal * 0.028;

  push();
  rotateX(rotX + random(-shake, shake));
  rotateY(rotY + random(-shake, shake));
  rotateZ(rotZ + random(-shake, shake));

  // 1. Draw tunnel corner lines
  strokeWeight(1.2 + beatVal * 1.5);
  stroke(35, 80, 95, 0.18 + beatVal * 0.22); // Faint golden/orange tunnel lines
  line(-tunnelW/2, -tunnelH/2, zFar, -tunnelW/2, -tunnelH/2, zNear);
  line(tunnelW/2, -tunnelH/2, zFar, tunnelW/2, -tunnelH/2, zNear);
  line(-tunnelW/2, tunnelH/2, zFar, -tunnelW/2, tunnelH/2, zNear);
  line(tunnelW/2, tunnelH/2, zFar, tunnelW/2, tunnelH/2, zNear);

  // 2. Draw accretion disk / golden aura (around black hole)
  push();
  translate(0, 0, zFar + 5);
  let numLayers = 40;
  let baseHue = 35; // Golden/orange
  if (window.currentChordColor) {
    let chordC = color(window.currentChordColor);
    baseHue = hue(chordC);
  }

  // Nonlinear accretion disk expansion
  let dRad = blackHoleRad + pow(beatVal, 2.0) * 35.0 + lowVal * 15.0;

  for (let i = 0; i < numLayers; i++) {
    let rad = dRad * (1.05 + i * 0.08 + beatVal * 0.15);
    let alpha = map(i, 0, numLayers, 0.28, 0.0);
    let hueVal = (baseHue + sin(frameCount * 0.02 + i * 0.15) * 22) % 360;

    noFill();
    stroke(hueVal, 92, 95, alpha);
    strokeWeight(4.0 + i * 0.4 + midVal * 6.0);
    ellipse(0, 0, rad * 2, rad * 2);
  }
  pop();

  // 3. Draw horizontal & vertical glowing cross lines (with high frequency flicker)
  push();
  translate(0, 0, zFar + 8);
  let crossHue = 35; // Gold/orange
  if (window.currentChordColor) {
    let chordC = color(window.currentChordColor);
    crossHue = hue(chordC);
  }

  let flicker = highVal > 0.4 ? random(0.7, 1.3) : 1.0;

  // Horizontal ray
  for (let w = 24; w >= 1.5; w -= 2.0) {
    let alpha = map(w, 1.5, 24, 0.45, 0.01) * flicker;
    stroke(crossHue, 95, 100, alpha);
    strokeWeight((w + highVal * 12.0) * (1.0 + beatVal * 0.4));
    line(-1000, 0, 1000, 0);
  }

  // Vertical ray
  for (let w = 24; w >= 1.5; w -= 2.0) {
    let alpha = map(w, 1.5, 24, 0.45, 0.01) * flicker;
    stroke(crossHue, 95, 100, alpha);
    strokeWeight((w + highVal * 12.0) * (1.0 + beatVal * 0.4));
    line(0, -800, 0, 800);
  }
  pop();

  // 4. Draw central black hole
  push();
  translate(0, 0, zFar + 10);
  fill(0, 0, 0, 1.0);
  noStroke();
  ellipse(0, 0, dRad * 2, dRad * 2);
  pop();

  // 5. Update & draw tunnel particles
  for (let p of particles) {
    p.update();
    p.draw();
  }

  pop();
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}

